"""Conservative density and developmental-moment PDE solver."""

from __future__ import annotations

from dataclasses import dataclass
import math

import numpy as np
import pandas as pd

from .config import SimulationConfig
from .dynamics import neuron_birth_rho, neuron_q, radial_glia_rho, stopping_velocity


@dataclass(frozen=True)
class PDEResult:
    """Truth fields generated by the cortical transport system."""

    z: np.ndarray
    time: np.ndarray
    cohort_table: pd.DataFrame
    q_over_time: np.ndarray
    velocity_by_cohort: dict[str, np.ndarray]
    velocity_over_time: np.ndarray
    velocity_stopping_points_over_time: np.ndarray
    density_by_cohort: dict[str, np.ndarray]
    moment_by_cohort: dict[str, np.ndarray]
    rho_by_cohort: dict[str, np.ndarray]
    radial_glia_density: np.ndarray
    radial_glia_rho: np.ndarray
    density_total: np.ndarray
    moment_total: np.ndarray
    rho_observed: np.ndarray
    rho_support_mask: np.ndarray
    explicit_steps: int
    dt_cfl: float
    dz: float


def _normalized_gaussian(
    coordinates: np.ndarray,
    *,
    center: float,
    sigma: float,
) -> np.ndarray:
    values = np.exp(-0.5 * ((coordinates - center) / sigma) ** 2)
    integral = float(np.trapezoid(values, coordinates))
    if integral <= 0.0:
        raise RuntimeError("Gaussian normalization failed.")
    return values / integral


def _gaussian_time_rate(t: float, *, center: float, sigma: float) -> float:
    return float(
        math.exp(-0.5 * ((t - center) / sigma) ** 2)
        / (sigma * math.sqrt(2.0 * math.pi))
    )


def _positive_upwind_flux(
    field: np.ndarray,
    velocity_interfaces: np.ndarray,
) -> np.ndarray:
    flux = np.zeros(len(field) + 1, dtype=float)
    flux[0] = 0.0
    flux[1:-1] = velocity_interfaces[1:-1] * field[:-1]
    flux[-1] = velocity_interfaces[-1] * field[-1]
    return flux


def _advect_source_step(
    field: np.ndarray,
    *,
    velocity_interfaces: np.ndarray,
    source: np.ndarray,
    dt: float,
    dz: float,
) -> np.ndarray:
    flux = _positive_upwind_flux(field, velocity_interfaces)
    updated = field - (dt / dz) * (flux[1:] - flux[:-1]) + dt * source
    return np.maximum(updated, 0.0)


def _cohort_table(config: SimulationConfig) -> pd.DataFrame:
    edges = np.asarray(
        config.stopping_layer_edges,
        dtype=float,
    )

    stopping_points = np.sort(
        np.asarray(
            config.stopping_points,
            dtype=float,
        )
    )[::-1]

    birth_times = np.asarray(
        config.birth_times,
        dtype=float,
    )

    n_cohorts = len(stopping_points)

    if len(birth_times) != n_cohorts:
        raise ValueError(
            "birth_times and stopping_points must have equal length."
        )

    return pd.DataFrame(
        {
            "cohort": [
                f"layer_{index + 1}"
                for index in range(n_cohorts)
            ],
            "birth_time": birth_times,
            "stopping_position": stopping_points,
            "layer_lower_edge": edges[:-1][::-1],
            "layer_upper_edge": edges[1:][::-1],
        }
    )


def _velocity_at_time(
    t: float,
    *,
    tissue_times: np.ndarray,
    profiles: np.ndarray,
) -> np.ndarray:
    """Linearly interpolate V(z,t) between tissue times."""
    if t <= tissue_times[0]:
        return profiles[0]

    if t >= tissue_times[-1]:
        return profiles[-1]

    left = int(
        np.searchsorted(
            tissue_times,
            t,
            side="right",
        )
        - 1
    )
    right = left + 1

    weight = (
        (t - tissue_times[left])
        / (tissue_times[right] - tissue_times[left])
    )

    return (
        (1.0 - weight) * profiles[left]
        + weight * profiles[right]
    )


def solve_cortical_pde(config: SimulationConfig) -> PDEResult:
    """Solve cohort density and ``rho``-moment equations at tissue times.

    For cohort ``k`` the solver advances

    ``d_t n_k + d_z(v_k n_k) = b_k``

    and

    ``d_t m_k + d_z(v_k m_k) = b_k rho_birth,k + n_k q_k``,

    where ``m_k=n_k rho_k``. Radial glia are stationary near ``z=0`` and are
    combined with all neuronal cohorts through a density-weighted mean.
    """
    config.validate()

    z = np.linspace(config.z_min, config.z_max, config.n_z)
    dz = float(z[1] - z[0])
    time = config.tissue_times
    cohort_table = _cohort_table(config)

    # The prescribed developmental source is constant over z and t.
    q_over_time = np.full(
        (len(time), len(z)),
        fill_value=config.constant_q,
        dtype=float,
    )

    z_interfaces = np.linspace(
        config.z_min - 0.5 * dz,
        config.z_max + 0.5 * dz,
        config.n_z + 1,
    )
    z_interfaces = np.clip(z_interfaces, config.z_min, config.z_max)

    birth_spatial_profile = _normalized_gaussian(
        z,
        center=config.birth_z_center,
        sigma=config.birth_z_sigma,
    )
    rg_density_profile = config.rg_total_mass * _normalized_gaussian(
        z,
        center=config.rg_z_center,
        sigma=config.rg_z_sigma,
    )

    stopping_points = cohort_table[
        "stopping_position"
    ].to_numpy(dtype=float)

    if len(stopping_points) != len(time) - 1:
        raise ValueError(
            "Need exactly one stopping point for every "
            "post-zero tissue time."
        )

    # t=0 is constant across all z.
    center_profiles = [
        np.full_like(
            z,
            config.peak_velocity,
            dtype=float,
        )
    ]
    interface_profiles = [
        np.full_like(
            z_interfaces,
            config.peak_velocity,
            dtype=float,
        )
    ]

    # Each later tissue time has a progressively lower stopping point.
    for stopping_point in stopping_points:
        center_profiles.append(
            stopping_velocity(
                z,
                peak_velocity=config.peak_velocity,
                stopping_point=float(stopping_point),
                deceleration_width=config.deceleration_width,
            )
        )

        interface_profiles.append(
            stopping_velocity(
                z_interfaces,
                peak_velocity=config.peak_velocity,
                stopping_point=float(stopping_point),
                deceleration_width=config.deceleration_width,
            )
        )

    velocity_over_time = np.stack(
        center_profiles,
        axis=0,
    )
    velocity_interfaces_over_time = np.stack(
        interface_profiles,
        axis=0,
    )

    velocity_stopping_points_over_time = np.concatenate(
        (
            [np.nan],
            stopping_points,
        )
    )

    # Retain this mapping for compatibility with existing package outputs.
    velocity_by_cohort = {
        row.cohort: velocity_over_time[index + 1]
        for index, row in enumerate(
            cohort_table.itertuples(index=False)
        )
    }

    maximum_velocity = float(
        np.max(
            np.abs(
                velocity_interfaces_over_time
            )
        )
    )
    if maximum_velocity <= 0.0:
        raise RuntimeError("The neuronal velocity field is identically zero.")
    dt_cfl = config.cfl * dz / maximum_velocity

    density_state = {
        name: np.zeros(config.n_z, dtype=float) for name in cohort_table["cohort"]
    }
    moment_state = {
        name: np.zeros(config.n_z, dtype=float) for name in cohort_table["cohort"]
    }
    density_snapshots = {name: [] for name in cohort_table["cohort"]}
    moment_snapshots = {name: [] for name in cohort_table["cohort"]}

    def save_snapshot() -> None:
        for name in cohort_table["cohort"]:
            density_snapshots[name].append(density_state[name].copy())
            moment_snapshots[name].append(moment_state[name].copy())

    save_snapshot()
    current_time = float(time[0])
    explicit_steps = 0

    for target_time in time[1:]:
        target_time = float(target_time)
        while current_time < target_time - 1e-14:
            dt = min(
                dt_cfl,
                target_time - current_time,
            )

            step_velocity = _velocity_at_time(
                current_time + 0.5 * dt,
                tissue_times=time,
                profiles=velocity_interfaces_over_time,
            )

            for row in cohort_table.itertuples(index=False):
                name = row.cohort
                birth_time = float(row.birth_time)
                density = density_state[name]
                moment = moment_state[name]

                birth_rate = config.cohort_total_mass * _gaussian_time_rate(
                    current_time,
                    center=birth_time,
                    sigma=config.birth_time_sigma,
                )
                birth_source = birth_rate * birth_spatial_profile
                inherited_rho = neuron_birth_rho(birth_time, config)
                q_value = float(
                    np.asarray(neuron_q(current_time, birth_time=birth_time, config=config))
                )

                density_new = _advect_source_step(
                    density,
                    velocity_interfaces=step_velocity,
                    source=birth_source,
                    dt=dt,
                    dz=dz,
                )
                moment_new = _advect_source_step(
                    moment,
                    velocity_interfaces=step_velocity,
                    source=birth_source * inherited_rho + density * q_value,
                    dt=dt,
                    dz=dz,
                )
                moment_new = np.minimum(
                    moment_new,
                    config.mature_neuron_rho * density_new + 1e-12,
                )

                density_state[name] = density_new
                moment_state[name] = moment_new

            current_time += dt
            explicit_steps += 1

        current_time = target_time
        save_snapshot()

    density_by_cohort = {
        name: np.asarray(snapshots, dtype=float)
        for name, snapshots in density_snapshots.items()
    }
    moment_by_cohort = {
        name: np.asarray(snapshots, dtype=float)
        for name, snapshots in moment_snapshots.items()
    }
    rho_by_cohort: dict[str, np.ndarray] = {}
    for name in cohort_table["cohort"]:
        density = density_by_cohort[name]
        moment = moment_by_cohort[name]
        rho_by_cohort[name] = np.divide(
            moment,
            density,
            out=np.full_like(moment, np.nan),
            where=density > 1e-12,
        )

    rg_rho_over_time = np.asarray(radial_glia_rho(time, config), dtype=float)
    rg_density_grid = np.broadcast_to(
        rg_density_profile,
        (config.n_timepoints, config.n_z),
    ).copy()
    rg_moment_grid = rg_density_grid * rg_rho_over_time[:, None]

    density_total = rg_density_grid.copy()
    moment_total = rg_moment_grid.copy()
    for name in cohort_table["cohort"]:
        density_total += density_by_cohort[name]
        moment_total += moment_by_cohort[name]

    rho_observed = np.divide(
        moment_total,
        density_total,
        out=np.full_like(moment_total, np.nan),
        where=density_total > 1e-14,
    )
    density_threshold = max(
        1e-14,
        config.density_support_fraction * float(np.max(density_total)),
    )
    rho_support_mask = np.isfinite(rho_observed) & (
        density_total > density_threshold
    )

    return PDEResult(
        z=z,
        time=time,
        cohort_table=cohort_table,
        q_over_time=q_over_time,
        velocity_by_cohort=velocity_by_cohort,
        velocity_over_time=velocity_over_time,
        velocity_stopping_points_over_time=(
            velocity_stopping_points_over_time
        ),
        density_by_cohort=density_by_cohort,
        moment_by_cohort=moment_by_cohort,
        rho_by_cohort=rho_by_cohort,
        radial_glia_density=rg_density_grid,
        radial_glia_rho=rg_rho_over_time,
        density_total=density_total,
        moment_total=moment_total,
        rho_observed=rho_observed,
        rho_support_mask=rho_support_mask,
        explicit_steps=explicit_steps,
        dt_cfl=dt_cfl,
        dz=dz,
    )

# FLOW_STP_TIME_INDEXED_VELOCITY_V2

# FLOW_STP_ANALYTIC_FIELDS_PDE_BEGIN


from dataclasses import MISSING as _DATACLASS_MISSING

from .dynamics import (
    flow_map as _analytic_flow_map,
    prescribed_q as _analytic_q,
    prescribed_rho as _analytic_rho,
    prescribed_velocity as _analytic_velocity,
)


def _construct_analytic_pde_result(
    **values,
):
    """Construct the installed PDEResult version and attach extra truth."""
    kwargs = {}

    for (
        name,
        field,
    ) in PDEResult.__dataclass_fields__.items():
        if name in values:
            kwargs[name] = values[name]

        elif field.default is not _DATACLASS_MISSING:
            continue

        elif (
            field.default_factory
            is not _DATACLASS_MISSING
        ):
            continue

        else:
            raise RuntimeError(
                "Analytic solver does not provide "
                f"required PDEResult field {name!r}."
            )

    result = PDEResult(**kwargs)

    # Add fields that may not yet be declared by the installed dataclass.
    for name, value in values.items():
        if not hasattr(result, name):
            object.__setattr__(
                result,
                name,
                value,
            )

    return result


def solve_cortical_pde(
    config: SimulationConfig,
) -> PDEResult:
    """Generate density and prescribed analytic F, V, rho, and q fields.

    Cohort densities are conservatively transported using the constant
    velocity derived from F(a,t)=a+U*t. Developmental rho is prescribed
    exactly as A*t+B*z*t+C*t^2, rather than reconstructed from a separately
    transported developmental moment.
    """
    config.validate()

    scalar_parameters = {
        "flow_speed": config.flow_speed,
        "rho_time_linear": (
            config.rho_time_linear
        ),
        "rho_space_time": (
            config.rho_space_time
        ),
        "rho_time_quadratic": (
            config.rho_time_quadratic
        ),
    }

    for name, value in scalar_parameters.items():
        if not np.isfinite(value):
            raise ValueError(
                f"{name} must be finite."
            )

    if config.flow_speed <= 0.0:
        raise ValueError(
            "flow_speed must be positive."
        )

    if config.rho_time_linear <= 0.0:
        raise ValueError(
            "rho_time_linear must be positive."
        )

    if config.rho_space_time <= 0.0:
        raise ValueError(
            "rho_space_time must be positive."
        )

    if config.rho_time_quadratic < 0.0:
        raise ValueError(
            "rho_time_quadratic must be nonnegative."
        )

    z = np.linspace(
        config.z_min,
        config.z_max,
        config.n_z,
    )

    dz = float(
        z[1] - z[0]
    )

    time = np.asarray(
        config.tissue_times,
        dtype=float,
    )

    cohort_table = _cohort_table(config)

    z_interfaces = np.linspace(
        config.z_min - 0.5 * dz,
        config.z_max + 0.5 * dz,
        config.n_z + 1,
    )

    z_interfaces = np.clip(
        z_interfaces,
        config.z_min,
        config.z_max,
    )

    birth_spatial_profile = _normalized_gaussian(
        z,
        center=config.birth_z_center,
        sigma=config.birth_z_sigma,
    )

    rg_density_profile = (
        config.rg_total_mass
        * _normalized_gaussian(
            z,
            center=config.rg_z_center,
            sigma=config.rg_z_sigma,
        )
    )

    # ------------------------------------------------------------------
    # Prescribed analytic truth
    # ------------------------------------------------------------------

    flow_over_time = _analytic_flow_map(
        z[None, :],
        time[:, None],
        config,
    )

    velocity_over_time = _analytic_velocity(
        z[None, :],
        time[:, None],
        config,
    )

    rho_over_time = _analytic_rho(
        z[None, :],
        time[:, None],
        config,
    )

    q_over_time = _analytic_q(
        z[None, :],
        time[:, None],
        config,
    )

    expected_q = (
        config.rho_time_linear
        + config.rho_space_time
        * z[None, :]
        + (
            2.0
            * config.rho_time_quadratic
            + config.flow_speed
            * config.rho_space_time
        )
        * time[:, None]
    )

    if not np.allclose(
        q_over_time,
        expected_q,
    ):
        raise RuntimeError(
            "Analytic q failed its identity check."
        )

    if not np.allclose(
        rho_over_time[0],
        0.0,
    ):
        raise RuntimeError(
            "rho must be exactly zero at t=0."
        )

    if np.any(
        np.diff(
            rho_over_time[1:],
            axis=1,
        )
        <= 0.0
    ):
        raise RuntimeError(
            "rho must increase over z at positive times."
        )

    if np.any(
        np.diff(
            rho_over_time,
            axis=0,
        )
        <= 0.0
    ):
        raise RuntimeError(
            "rho must increase over time."
        )

    rho_maximum = float(
        np.max(rho_over_time)
    )

    if rho_maximum > (
        config.mature_neuron_rho
        + 1e-12
    ):
        raise ValueError(
            "The prescribed rho exceeds "
            "mature_neuron_rho. Reduce A, B, or C."
        )

    # ------------------------------------------------------------------
    # Conservatively transport cohort densities using V=U
    # ------------------------------------------------------------------

    velocity_interfaces = np.full(
        len(z_interfaces),
        config.flow_speed,
        dtype=float,
    )

    dt_cfl = (
        config.cfl
        * dz
        / config.flow_speed
    )

    cohort_names = list(
        cohort_table["cohort"]
    )

    density_state = {
        name: np.zeros(
            config.n_z,
            dtype=float,
        )
        for name in cohort_names
    }

    density_snapshots = {
        name: []
        for name in cohort_names
    }

    def save_snapshot() -> None:
        for name in cohort_names:
            density_snapshots[name].append(
                density_state[name].copy()
            )

    save_snapshot()

    current_time = float(
        time[0]
    )
    explicit_steps = 0

    for target_time in time[1:]:
        target_time = float(
            target_time
        )

        while (
            current_time
            < target_time - 1e-14
        ):
            dt = min(
                dt_cfl,
                target_time - current_time,
            )

            for row in (
                cohort_table
                .itertuples(index=False)
            ):
                name = row.cohort

                birth_rate = (
                    config.cohort_total_mass
                    * _gaussian_time_rate(
                        current_time,
                        center=float(
                            row.birth_time
                        ),
                        sigma=(
                            config.birth_time_sigma
                        ),
                    )
                )

                birth_source = (
                    birth_rate
                    * birth_spatial_profile
                )

                density_state[name] = (
                    _advect_source_step(
                        density_state[name],
                        velocity_interfaces=(
                            velocity_interfaces
                        ),
                        source=birth_source,
                        dt=dt,
                        dz=dz,
                    )
                )

            current_time += dt
            explicit_steps += 1

        current_time = target_time
        save_snapshot()

    density_by_cohort = {
        name: np.asarray(
            snapshots,
            dtype=float,
        )
        for name, snapshots
        in density_snapshots.items()
    }

    # rho is prescribed identically for every cohort.
    rho_by_cohort = {
        name: rho_over_time.copy()
        for name in cohort_names
    }

    moment_by_cohort = {
        name: (
            density_by_cohort[name]
            * rho_over_time
        )
        for name in cohort_names
    }

    radial_glia_density = np.broadcast_to(
        rg_density_profile,
        rho_over_time.shape,
    ).copy()

    radial_glia_rho = rho_over_time.copy()

    density_total = (
        radial_glia_density.copy()
    )

    for name in cohort_names:
        density_total += (
            density_by_cohort[name]
        )

    moment_total = (
        density_total
        * rho_over_time
    )

    # No density weighting or moment division is used to define rho.
    rho_observed = rho_over_time.copy()

    # rho is analytically defined throughout the entire z domain.
    rho_support_mask = np.isfinite(
        rho_observed
    )

    velocity_by_cohort = {
        name: (
            velocity_over_time[0].copy()
        )
        for name in cohort_names
    }

    # Retained only for compatibility with earlier notebook cells.
    # Stopping points no longer control velocity.
    velocity_stopping_points_over_time = (
        np.full(
            len(time),
            np.nan,
            dtype=float,
        )
    )

    values = {
        "z": z,
        "time": time,
        "cohort_table": cohort_table,
        "flow_over_time": flow_over_time,
        "velocity_over_time": (
            velocity_over_time
        ),
        "velocity_stopping_points_over_time": (
            velocity_stopping_points_over_time
        ),
        "q_over_time": q_over_time,
        "rho_over_time": rho_over_time,
        "velocity_by_cohort": (
            velocity_by_cohort
        ),
        "density_by_cohort": (
            density_by_cohort
        ),
        "moment_by_cohort": (
            moment_by_cohort
        ),
        "rho_by_cohort": rho_by_cohort,
        "radial_glia_density": (
            radial_glia_density
        ),
        "radial_glia_rho": (
            radial_glia_rho
        ),
        "density_total": density_total,
        "moment_total": moment_total,
        "rho_observed": rho_observed,
        "rho_support_mask": (
            rho_support_mask
        ),
        "explicit_steps": explicit_steps,
        "dt_cfl": dt_cfl,
        "dz": dz,
    }

    return _construct_analytic_pde_result(
        **values
    )


# FLOW_STP_ANALYTIC_FIELDS_PDE_END
